const D = { energy: .5, scale: 1, density: .55, speed: 1, growth: .6, decay: .55, hue: 108, x: .5, y: .74, style: 'birch', act: 'summer', seed: 0, alpha: 1 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u = Math.min(width, height);
const fr = i => { const q = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return q - Math.floor(q); };
const hw = h => ((h % 360) + 360) % 360;
const ho = P.hue - 108;
const L3 = (a, b, f) => [a[0] + (b[0]-a[0])*f, a[1] + (b[1]-a[1])*f, a[2] + (b[2]-a[2])*f];
const sh = c => [hw(c[0] + ho), c[1], c[2]];
const NR = 3;                                     // sapling ranks, 0 = deepest

// ---------------- styles ----------------
const STY = {
  // birch saplings in a dead concrete hall under cold north light — urbex large-format
  birch:       { air:[196,12,30], wall:[36,7,38], wallD:[214,10,16], win:[196,10,86], trunk:[40,4,80],
                 leaf:[96,34,52], leafL:[86,40,72], moss:[104,40,26], rub:[32,8,28], wat:[200,16,26], flat:0, half:0, grain:24 },
  // high summer — the hall has lost. Heavy ivy, warm green, gold light through the windows.
  verdant:     { air:[86,26,34], wall:[42,14,36], wallD:[70,16,15], win:[46,40,92], trunk:[44,10,72],
                 leaf:[104,58,46], leafL:[82,62,68], moss:[112,54,24], rub:[38,16,26], wat:[96,30,22], flat:0, half:0, grain:28 },
  // winter — bare stems, snow blown in through the roof, blue-white and silent
  frost:       { air:[208,10,52], wall:[210,6,44], wallD:[216,10,22], win:[204,6,94], trunk:[38,6,66],
                 leaf:[30,10,58], leafL:[200,6,84], moss:[150,14,30], rub:[210,6,40], wat:[206,12,34], flat:0, half:0, grain:20 },
  // ABSTRACTED: chiaroscuro — no local colour at all, every form emerges from the light falloff
  chiaroscuro: { air:[34,6,18], wall:[34,5,26], wallD:[34,8,8], win:[36,3,98], trunk:[34,3,60],
                 leaf:[34,5,22], leafL:[34,4,44], moss:[34,6,12], rub:[34,5,16], wat:[34,4,20], flat:0, half:0, grain:14 },
  // ABSTRACTED: a CMYK four-plate halftone — rosette screens, misregistered, no continuous tone
  halftone:    { air:[186,30,74], wall:[38,22,70], wallD:[320,40,44], win:[52,16,96], trunk:[38,10,86],
                 leaf:[150,64,58], leafL:[62,70,80], moss:[172,60,40], rub:[318,26,56], wat:[196,44,50], flat:1, half:1, grain:6 }
};
const st = STY[P.style] || STY.birch;

const en = Math.max(0, Math.min(1, P.energy));
const gr = Math.max(0, Math.min(1, P.growth));
const dc = Math.max(0, Math.min(1, P.decay));
const fy = height * P.y;                          // the floor line at the back wall
const lx = width * P.x;                           // where the roof has fallen in
const key = width + 'x' + height + '|' + P.style + '|' + P.seed + '|' + Math.round(P.hue) + '|' + P.scale.toFixed(2) + '|' + P.density.toFixed(2) + '|' + P.growth.toFixed(2) + '|' + P.decay.toFixed(2) + '|' + P.y.toFixed(3) + '|' + P.x.toFixed(3);

if (!S.room || S.key !== key) {
  const W = Math.max(2, Math.ceil(width)), H = Math.max(2, Math.ceil(height));
  const mk = (w, h) => { const g = createGraphics(Math.max(2, Math.ceil(w)), Math.max(2, Math.ceil(h))); g.colorMode(g.HSB, 360, 100, 100, 100); return g; };
  if (S.room) { S.room.remove(); S.can.forEach(c => c.g.remove()); S.haze.remove(); }
  S.room = mk(W, H); S.haze = mk(W, H);

  const q = S.room; q.noStroke();
  const airC = sh(st.air), wallC = sh(st.wall), wallD = sh(st.wallD), winC = sh(st.win),
        trunkC = sh(st.trunk), mossC = sh(st.moss), rubC = sh(st.rub);

  // --- the hall: back wall, its value falling away from the windows ---
  for (let yy = 0; yy < H; yy++) {
    const f = Math.min(1, yy / Math.max(1, fy));
    const c = L3(L3(wallD, wallC, .7), wallD, Math.pow(f, 1.6) * .7);
    q.fill(c[0], c[1], c[2]); q.rect(0, yy, W, 1);
  }
  // plaster loss — the wall is a map of what has fallen off it. Texture over flat fill.
  const npl = Math.floor(160 * (.3 + dc));
  for (let i = 0; i < npl; i++) {
    const px = fr(i * 3 + 11) * W, py = fr(i * 3 + 12) * fy;
    const r = u * (.02 + fr(i * 3 + 13) * .10) * (.4 + dc);
    const c = fr(i) > .45 ? L3(wallD, mossC, .4 + fr(i) * .5) : L3(wallC, rubC, fr(i));
    q.fill(c[0], c[1] * (.6 + fr(i) * .8), Math.max(2, c[2] + (fr(i * 5) - .5) * 16), 16 + fr(i * 7) * 26);
    q.beginShape();
    for (let a = 0; a < 9; a++) { const an = a / 9 * Math.PI * 2; const rr = r * (.5 + fr(i * 11 + a) * .8); q.vertex(px + Math.cos(an) * rr, py + Math.sin(an) * rr * .8); }
    q.endShape(q.CLOSE);
  }
  // water staining running down from the roof failure
  for (let i = 0; i < 26; i++) {
    const px = fr(i * 3 + 31) * W;
    q.fill(wallD[0], wallD[1] + 8, Math.max(2, wallD[2] * .7), 12 + fr(i) * 14);
    q.rect(px, 0, u * (.006 + fr(i * 2) * .02), fy * (.3 + fr(i * 4) * .7));
  }

  // --- the tall windows: the light source, and the only bright thing at the back ---
  const nw = 3 + Math.floor(P.density * 3);
  const winY = fy * .18, winH = fy * .60, winW = W / (nw * 2.2);
  for (let i = 0; i < nw; i++) {
    const wx = W * ((i + .5) / nw) - winW / 2;
    q.fill(winC[0], winC[1], winC[2], 92); q.rect(wx, winY, winW, winH);
    // the glow bleeding onto the wall around each opening
    for (let j = 4; j >= 0; j--) { q.fill(winC[0], winC[1] * .5, winC[2], 5 * (1 - j * .15)); q.rect(wx - j * u * .012, winY - j * u * .012, winW + j * u * .024, winH + j * u * .024); }
    // mullions + the panes that are gone
    q.noFill(); q.strokeWeight(Math.max(.8, u * .0022));
    q.stroke(wallD[0], wallD[1], Math.max(2, wallD[2] * .5), 88);
    for (let r = 0; r <= 6; r++) q.line(wx, winY + winH * r / 6, wx + winW, winY + winH * r / 6);
    q.line(wx + winW / 2, winY, wx + winW / 2, winY + winH);
    q.rect(wx, winY, winW, winH);
    q.noStroke();
    for (let r = 0; r < 12; r++) {   // shards still in the frame
      if (fr(i * 31 + r) > .45 * dc) continue;
      const cxp = wx + (r % 2) * winW / 2, cyp = winY + Math.floor(r / 2) * winH / 6;
      q.fill(wallD[0], wallD[1], wallD[2], 60);
      q.triangle(cxp, cyp, cxp + winW / 2, cyp, cxp + winW * (fr(r) * .5), cyp + winH / 6 * fr(r + 3));
    }
    // ivy has got in and is coming down the reveal
    const nv = Math.floor(6 * gr);
    for (let v = 0; v < nv; v++) {
      const vx = wx + fr(i * 17 + v) * winW;
      q.noFill(); q.strokeWeight(Math.max(.6, u * .0016));
      q.stroke(mossC[0], mossC[1], Math.max(3, mossC[2] + fr(v) * 16), 70);
      q.beginShape();
      for (let s2 = 0; s2 <= 8; s2++) { const f = s2 / 8; q.vertex(vx + Math.sin(f * 5 + fr(v) * 6) * u * .012, winY + f * winH * (.4 + fr(i + v) * .6)); }
      q.endShape(); q.noStroke();
    }
  }

  // --- the roof, fallen in over P.x. Sky in the hole; the rest is a rotted deck. ---
  const holeW = u * (.22 + .26 * dc) * P.scale;
  q.fill(airC[0], airC[1] * .5, Math.min(99, airC[2] + 44), 92);
  q.beginShape();
  q.vertex(lx - holeW, -10); q.vertex(lx + holeW, -10);
  for (let a = 0; a <= 12; a++) { const f = a / 12; q.vertex(lx + holeW * (1 - 2 * f), fy * (.06 + .12 * Math.sin(f * 3.1 + fr(3) * 6) + .06 * Math.sin(f * 9 + fr(4) * 6))); }
  q.endShape(q.CLOSE);
  q.fill(wallD[0], wallD[1], Math.max(2, wallD[2] * .55), 96);
  q.beginShape(); q.vertex(-10, -10); q.vertex(W + 10, -10); q.vertex(W + 10, fy * .10);
  for (let xx = W + 10; xx >= -10; xx -= 14) {
    const inHole = Math.abs(xx - lx) < holeW;
    const n = Math.sin(xx * .008 + fr(5) * 6) * .4 + Math.sin(xx * .021) * .2;
    q.vertex(xx, inHole ? fy * (.05 + n * .04) - fy * .3 : fy * (.09 + n * .05));
  }
  q.vertex(-10, fy * .10); q.endShape(q.CLOSE);
  // exposed joists over the hole
  for (let i = 0; i < 7; i++) {
    const jx = lx - holeW + (i / 6) * holeW * 2;
    q.fill(wallD[0], wallD[1], Math.max(2, wallD[2] * .4), 70 * (fr(i + 7) > .3 * dc ? 1 : 0));
    q.rect(jx, -10, u * .008, fy * (.08 + fr(i) * .12));
  }

  // --- the floor: rubble, moss carpet, standing water. Never a flat slab. ---
  q.fill(rubC[0], rubC[1], rubC[2]); q.rect(0, fy, W, H - fy);
  const nrb = Math.floor(340 * (.4 + dc));
  for (let i = 0; i < nrb; i++) {
    const f = Math.pow(fr(i * 3 + 41), 1.6);
    const py = fy + f * (H - fy), px = fr(i * 3 + 42) * W;
    const r = u * (.004 + fr(i * 3 + 43) * .016) * (.3 + f * 1.8);
    const c = fr(i * 5) < gr * .5 ? L3(mossC, sh(st.leaf), fr(i)) : L3(rubC, wallC, fr(i * 7));
    q.fill(c[0], c[1] * (.6 + fr(i) * .8), Math.max(2, c[2] + (fr(i * 9) - .5) * 20), 40 + fr(i * 3) * 46);
    q.ellipse(px, py, r * (1 + fr(i * 11)), r * .7);
  }
  S.pools = [];
  for (let i = 0; i < 5; i++) {
    const f = .1 + fr(i * 5 + 51) * .8;
    const py = fy + f * (H - fy), px = fr(i * 5 + 52) * W;
    const pw = u * (.10 + fr(i * 5 + 53) * .3) * (.3 + f * 1.6), ph = u * .02 * (.3 + f * 1.8);
    S.pools.push({ x: px, y: py, w: pw, h: ph });
  }

  // --- the saplings. Trunks are baked; canopies become sprites so each can sway alone. ---
  S.can = [];
  const leafC = sh(st.leaf), leafL = sh(st.leafL);
  for (let L = 0; L < NR; L++) {
    const near = L / (NR - 1);
    const haze = (1 - near) * .5;
    const n = Math.max(1, Math.round((1 + fr(L * 13 + 61) * 2 + P.density * 4) * (.4 + gr)));
    for (let i = 0; i < n; i++) {
      const id = L * 167 + i * 29 + 11;
      const bx = W * ((i + .5 + (fr(id + 1) - .5) * .8) / n);
      const by = fy + Math.pow(.15 + near * .8, 1.4) * (H - fy);
      const th = u * (.16 + near * .34 + fr(id + 2) * .14) * P.scale * (.5 + gr * .8);
      const tw = Math.max(1.2, th * .014);
      const tc = L3(trunkC, L3(wallC, airC, .5), haze);
      // trunk + fine branching, baked into the room
      q.noStroke();
      const lean = (fr(id + 3) - .5) * .16;
      q.fill(tc[0], tc[1], tc[2], 100);
      q.beginShape();
      for (let s2 = 0; s2 <= 8; s2++) { const f = s2 / 8; q.vertex(bx + lean * th * f * f - tw * (1 - f * .6) / 2, by - th * f); }
      for (let s2 = 8; s2 >= 0; s2--) { const f = s2 / 8; q.vertex(bx + lean * th * f * f + tw * (1 - f * .6) / 2, by - th * f); }
      q.endShape(q.CLOSE);
      if (!st.flat) {   // birch lenticels — the dark dashes that make bark read as bark
        for (let s2 = 0; s2 < 9; s2++) {
          const f = fr(id * 7 + s2);
          q.fill(tc[0], tc[1] + 6, Math.max(2, tc[2] * .45), 60);
          q.rect(bx + lean * th * f * f - tw * .4, by - th * f, tw * (.5 + fr(s2) * .5), Math.max(.8, tw * .25));
        }
      }
      q.strokeWeight(Math.max(.5, tw * .5)); q.noFill();
      for (let b = 0; b < 4; b++) {
        const f = .5 + fr(id * 5 + b) * .45;
        const a = (fr(id * 3 + b) > .5 ? 1 : -1) * (.6 + fr(id + b) * .7);
        q.stroke(tc[0], tc[1], Math.max(2, tc[2] * .8), 90);
        q.line(bx + lean * th * f * f, by - th * f, bx + lean * th * f * f + Math.cos(-1.57 + a) * th * .2, by - th * f + Math.sin(-1.57 + a) * th * .2);
      }
      q.noStroke();

      // canopy sprite: a stipple cloud of small leaf marks. Not a cartoon blob.
      const cr = th * (.34 + fr(id + 4) * .2);
      const cg = mk(cr * 2.4, cr * 2.4);
      const nl = Math.floor(70 * (.4 + P.density) * (.4 + gr));
      cg.noStroke();
      for (let l = 0; l < nl; l++) {
        const a = fr(id * 11 + l) * Math.PI * 2, rr = Math.pow(fr(id * 13 + l * 3), .55) * cr;
        const lc = L3(L3(leafC, leafL, fr(id * 17 + l)), L3(wallC, airC, .5), haze);
        cg.fill(lc[0], lc[1] * (.7 + fr(l) * .6), Math.max(3, lc[2] + (fr(l * 3) - .5) * 22), st.flat ? 90 : 50 + fr(l * 5) * 40);
        cg.push(); cg.translate(cr * 1.2 + Math.cos(a) * rr, cr * 1.2 + Math.sin(a) * rr * .85);
        cg.rotate(fr(id + l) * 6.3);
        cg.ellipse(0, 0, cr * (.06 + fr(l * 7) * .07), cr * (.03 + fr(l * 9) * .035));
        cg.pop();
      }
      S.can.push({ g: cg, x: bx + lean * th, y: by - th, r: cr, near: near, ph: fr(id + 6) * 6.3, sp: .8 + fr(id + 7) * .7 });
    }
  }

  // --- a tileable haze bank: dust and pollen hanging in the hall ---
  const hC = L3(airC, sh(st.win), .4);
  S.haze.noStroke();
  for (let i = 0; i < 8; i++) {
    const bx = fr(i * 5 + 71) * W, by = fr(i * 5 + 72) * H;
    const bw = u * (.3 + fr(i * 5 + 73) * .7), bhh = u * (.1 + fr(i * 5 + 74) * .3);
    for (let rep = -1; rep <= 1; rep++) for (let kk = 0; kk < 4; kk++) {
      S.haze.fill(hC[0], hC[1] * (1 - kk * .1), Math.min(99, hC[2] + kk * 2), 8 * (1 - kk * .2));
      S.haze.ellipse(bx + rep * W, by + kk * bhh * .1, bw * (1 - kk * .13), bhh * (1 - kk * .1));
    }
  }
  S.key = key;
}

// ---------------- act: the season, over minutes ----------------
const sec = ((Math.floor(K.section) % 8) + 8) % 8;
const ACT = { summer: { w: .5 + sec * .05, l: .95 }, gale: { w: 1.5 + sec * .12, l: .8 }, dusk: { w: .35, l: 1.1 - sec * .08 } };
const act = ACT[P.act] || ACT.summer;
// the wind: three incommensurate real-time terms. It never returns to the same gust.
const wind = (.9 * Math.sin(K.t * .61) + .5 * Math.sin(K.t * 1.43 + 1.7) + .32 * Math.sin(K.t * 2.29)) * act.w * P.speed;

noStroke();
image(S.room, 0, 0);

// ---------------- the light coming through the roof failure and the windows ----------------
const winC2 = sh(st.win);
if (!st.half) {
  blendMode(ADD);
  const gg = (.3 + .7 * en) * act.l * (.8 + .2 * K.swell) + A.lowmid * .16;
  const sx = lx + Math.sin(K.t * .0089) * width * .04;      // the sun crawls, over minutes
  for (let i = 4; i >= 0; i--) {
    fill(winC2[0], winC2[1] * (.6 - i * .1), winC2[2], (2 + 5 * gg) * (1 - i * .15));
    // a soft wide wash from the hole, never a hard god-ray shaft
    quad(sx - u * (.10 + i * .05) * P.scale, 0, sx + u * (.10 + i * .05) * P.scale, 0,
         sx + u * (.20 + i * .12) * P.scale, height, sx - u * (.20 + i * .12) * P.scale, height);
  }
  blendMode(BLEND);
}

// ---------------- canopies: each sapling sways on its own phase ----------------
if (S.can) {
  for (let i = 0; i < S.can.length; i++) {
    const c = S.can[i];
    const sw = wind * (.02 + .05 * c.near) * c.sp + Math.sin(K.t * (1.1 + i * .17) + c.ph) * .012 * (.3 + act.w);
    push();
    translate(c.x, c.y);
    rotate(sw);
    image(c.g, -c.r * 1.2, -c.r * 1.2);
    pop();
  }
}

// ---------------- ivy hanging off the broken deck, swaying ----------------
const mossC2 = sh(st.moss);
const niv = Math.floor(5 + P.density * 7 * gr);
noFill();
for (let i = 0; i < niv; i++) {
  const ix = width * ((i + .5) / niv) + (fr(i * 3 + 81) - .5) * width * .1;
  const il = u * (.10 + fr(i * 3 + 82) * .28) * gr * P.scale;
  strokeWeight(Math.max(.6, u * .0016));
  stroke(mossC2[0], mossC2[1], Math.max(3, mossC2[2] + fr(i) * 20), 70);
  beginShape();
  for (let s2 = 0; s2 <= 9; s2++) {
    const f = s2 / 9;
    vertex(ix + Math.sin(f * 4 + fr(i) * 6.3) * u * .015 + wind * f * f * u * .018 * (.5 + fr(i) * .8), height * .05 + f * il);
  }
  endShape();
  noStroke();
  for (let l = 0; l < 7; l++) {   // ivy leaves on the strand
    const f = (l + 1) / 8;
    const lc = L3(mossC2, sh(st.leafL), fr(i * 7 + l) * .6);
    fill(lc[0], lc[1], lc[2], 66);
    ellipse(ix + Math.sin(f * 4 + fr(i) * 6.3) * u * .015 + wind * f * f * u * .018 * (.5 + fr(i) * .8) + (fr(i + l) - .5) * u * .012,
            height * .05 + f * il, u * .012 * (.6 + fr(l) * .6), u * .009);
  }
  noFill();
}
noStroke();

// ---------------- standing water: shimmering, holding the window light ----------------
if (S.pools && !st.half) {
  blendMode(P.style === 'chiaroscuro' ? ADD : BLEND);
  const watC = sh(st.wat);
  for (let i = 0; i < S.pools.length; i++) {
    const p = S.pools[i];
    fill(watC[0], watC[1], watC[2], 70); ellipse(p.x, p.y, p.w, p.h);
    for (let j = 0; j < 4; j++) {
      const sm = .5 + .5 * (Math.sin(K.t * (.61 + j * .09) + i * 2.1) * .55 + Math.sin(K.t * 1.43 + j) * .3 + Math.sin(K.t * 2.29 + i) * .15);
      const gain = (.3 + .7 * en) * (.35 + .65 * sm) + A.rms * .3;
      fill(winC2[0], winC2[1] * .4, winC2[2], (8 + 26 * gain));
      ellipse(p.x + (fr(i * 5 + j) - .5) * p.w * .5, p.y + (fr(i * 7 + j) - .5) * p.h * .4, p.w * (.1 + .3 * sm), p.h * .22);
    }
  }
  blendMode(BLEND);
}

// ---------------- dust and pollen turning in the light ----------------
const W2 = S.haze.width;
const hx = ((-K.t * u * .0026 * P.speed % W2) + W2) % W2;
image(S.haze, hx - W2, Math.sin(K.t * .019) * u * .01); image(S.haze, hx, Math.sin(K.t * .019) * u * .01);
const nd = Math.floor(18 + P.density * 30);
blendMode(ADD);
for (let i = 0; i < nd; i++) {
  const life = ((K.t * (.02 + fr(i * 3 + 91) * .05) * P.speed + fr(i * 3 + 92)) % 1);
  const dx2 = lx + (fr(i * 3 + 93) - .5) * u * .7 * P.scale + Math.sin(K.t * (.3 + i * .07) + i) * u * .02;
  const dy2 = (1 - life) * height;
  const fade = Math.sin(Math.PI * life);
  fill(winC2[0], winC2[1] * .3, winC2[2], (10 + 30 * en) * fade * (.3 + .7 * Math.max(0, 1 - Math.abs(dx2 - lx) / (u * .45))));
  ellipse(dx2, dy2, u * .0035 * (.5 + fr(i) * 1.2), u * .0035 * (.5 + fr(i) * 1.2));
}
blendMode(BLEND);

// ---------------- CMYK rosette screen, if that's the style ----------------
if (st.half) {
  const cell = Math.max(4, u * .009);
  for (let gy = 0; gy < height; gy += cell) for (let gx = 0; gx < width; gx += cell) {
    const n = (Math.sin(gx * .04 + gy * .021) + Math.sin(gx * .017 - gy * .033 + K.t * .05)) * .25 + .5;
    fill(hw(st.wallD[0] + ho), st.wallD[1], st.wallD[2], 26);
    ellipse(gx + cell * .5, gy + cell * .5, cell * .42 * n, cell * .42 * n);
  }
}

if (st.grain > 6) {
